        update_data = {
            "name": "更新后数据1",
            "sku_code": "更新后数据2"
        }
        result = SKURepository.update(unit_test_db, entity, update_data)
        
        # 验证所有字段已更新
        assert result.name == "更新后数据1"
        assert result.sku_code == "更新后数据2"
        
        # 验证持久化
        unit_test_db.expire_all()
        db_entity = unit_test_db.query(SKU).filter_by(id=entity.id).first()
        assert db_entity.name == "更新后数据1"
        assert db_entity.sku_code == "更新后数据2"
    
