    def test_soft_delete_success(self, unit_test_db: Session):
        """测试soft_delete - 删除成功"""
        # 准备测试数据
        from tests.factories.product_catalog_factories import ProductCatalogFactoryManager
        ProductCatalogFactoryManager.setup_factories(unit_test_db)
        # 准备依赖实体: Brand
        from tests.factories.product_catalog_factories import BrandFactory
        brand = BrandFactory.create()
        # 准备依赖实体: Category
        from tests.factories.product_catalog_factories import CategoryFactory
        category = CategoryFactory.create(parent_id=None)
        # 准备依赖实体: Product
        from tests.factories.product_catalog_factories import ProductFactory
        product = ProductFactory.create(brand_id=brand.id, category_id=category.id)
        entity = SKU(sku_code="TEST待删除数据", price=Decimal("99.99"), is_active=True, product_id=product.id)
        unit_test_db.add(entity)
        unit_test_db.commit()
        entity_id = entity.id
        
        # 执行Repository方法（传递对象）
        SKURepository.soft_delete(unit_test_db, entity)
        unit_test_db.commit()  # 提交删除操作
        
        # 验证软删除
        unit_test_db.expire_all()
        db_entity = unit_test_db.query(SKU).filter_by(id=entity_id).first()
        assert db_entity is not None  # 记录仍存在
        # 验证软删除标记（根据模型字段选择）
        if hasattr(db_entity, 'is_deleted'):
            assert db_entity.is_deleted == True
        if hasattr(db_entity, 'is_active'):
            assert db_entity.is_active == False

